root=Path(__file__).resolve().parent.parent;folder=root/'style-atlas/records/presenter-180'
sectors=runpy.run_path(str(folder/'briefs.py'))['SECTORS'];direct=runpy.run_path(str(folder/'compositions.py'))['direction']
def slug(value):return ''.join(c for c in unicodedata.normalize('NFKD',value.lower()) if not unicodedata.combining(c)).replace(',','').replace(' ','-')
rows=[]
for sector,name,environment,styles in sectors:
 for i,(title,topic,mechanism,reveal,interaction,resolution) in enumerate(styles):rows.append({'id':'explicador-'+sector+'-'+slug(title),'name':title,'sector':sector,'sectorName':name,'environment':environment,'topic':topic,'mechanism':mechanism,'states':['Demonstre a situação prática: '+topic+'. A relação explicada ainda está em construção.',reveal,interaction,resolution],'variantIndex':i})
original=[r for r in rows if r['variantIndex']<4 and r['sector'] not in ['revendas-veiculos','livrarias','bares']];extras=[r for r in rows if r not in original];rows=original+extras
assert len(rows)==145 and len({r['id'] for r in rows})==145 and len(original)==120 and len(extras)==25
rows+=runpy.run_path(str(folder/'specialist-briefs.py'))['ROWS']
assert len(rows)==185 and len({r['id'] for r in rows})==185
