jobs=[]
for k,s in enumerate(rows):
 person,wardrobe=people[(k*5+k//4)%len(people)];s['presenter']=person;s['wardrobe']=wardrobe
 if s['sector'] in ['clinicas','laboratorios','farmacias','fisioterapia','nutricao']:s['wardrobe']='clean practical professional uniform over a contemporary plain top; hair secured when needed, no loose jewelry in the work area'
 if s['sector']=='bares':s['presenter']+='; all people visibly adult and at least 25 years old'
 if s['sector'] in ['cafeterias','confeitarias','bares']:s['wardrobe']+='; clean contemporary practical apron, hair kept away from food, no loose jewelry touching preparation'
 if s['sector']=='revendas-veiculos' and s['variantIndex'] in [1,3]:s['environment']='a real MOTORCYCLE dealership; the main product is a parked motorcycle with an actual cockpit, wheels, chain and seat; the demonstration is stationary, not riding; other motorcycles in background'
 if s['sector']=='revendas-veiculos' and s['variantIndex']==2:s['environment']='a real dealership; compare a parked compact car and a parked motorcycle for everyday use; both clearly visible; realistic normal forecourt'
 if k>=145:
  person,unused=people[(k*5+k//4)%12];s['presenter']=person
  if s['sector']=='dentistas':
   s['presenter']+='; a young adult dentist, natural modest teeth and relaxed expression, not a beauty-model smile'
   s['wardrobe']=['clean muted teal contemporary dental scrubs','clean tailored white coat over navy clinical scrubs','clean pale blue contemporary dental uniform','clean sage dental scrubs'][k%4]+'; practical secured hair, no loose jewelry, no invented credentials or professional registration'
  elif s['domain']['profile']=='alto padrão':s['wardrobe']=['well-fitted stone linen blazer over a neutral top and tailored trousers','elegant navy contemporary tailoring, neat open-collar shirt, understated watch','refined ecru blouse with modern tailored dark trousers, discreet accessories','well-cut warm gray suit with a fine-knit polo and clean leather shoes'][k%4]
  else:s['wardrobe']=['neat modern blue shirt and tailored neutral trousers','natural linen blazer over a simple top, straight trousers','clean contemporary knit polo and neat chinos','structured olive blouse and dark tailored trousers'][k%4]
  if 'galpão' in s['name'].lower():s['wardrobe']+='; appropriate site safety vest and hard hat when entering the logistics work area'
 if s.get('domain',{}).get('kind')=='business_education':s['wardrobe']=['plain charcoal cotton tee and dark straight jeans with a relaxed work overshirt','modern indigo shirt with sleeves rolled and natural tailored trousers','textured neutral knit top and contemporary casual linen jacket','sage cotton blouse and wide-leg dark jeans, discreet everyday accessories'][k%4]
 d=s.get('customDirection') or direct(s,k);s['depthComposition']=d
 s['creativeDirection']={'version':1,'visualMode':s['mechanism'],'presenterBlocking':d['blocking'],'compositionIdea':s['states'][2]+' '+d['graphicEvolution'][2],'shotLanguage':d['camera'],'graphicMaterial':'chosen_by_function_no_default_panel','fixedPresenterSide':False,'digitalMirroringDefault':False,'motionFollowsExplanation':True,'sourceCoverageRequired':True,'conceptualReferenceOnly':True,'commercialPurpose':s['topic'],'referenceLens':'ultrarealistic_commercial_social','narrativeStructure':d['structure'],'typographyDirection':d['typography'],'depthComposition':d}
 common="""Create ONE ULTRA-REALISTIC edited EXPLAINER VIDEO storyboard. Portrait overall canvas with an exact 2x2 grid of FOUR COMPLETE INDEPENDENT portrait frames. High resolution. No outside title, margins or gutters. Each quadrant is a different real camera shot of the SAME fictional person with the SAME clothes, place and objects. It must show an ambitious PROFESSIONALLY COMPOSITED SOCIAL MEDIA VIDEO with graphics BEING BUILT IN THE REAL SCENE AS THE PERSON SPEAKS AND ACTS. This is NOT a person explaining next to a ready-made static diagram or panel. Make the intended layering and transformations plainly visible in the frames.

CORE DEPTH: original believable environment / explanatory element BEHIND body or an observed hand / person or hands / explanatory FOREGROUND. Use precise occlusion, perspective, scale, grounded soft shadows and contact when applicable: a fingertip partly hides a model, a line goes BEHIND the forearm then emerges IN FRONT, the person crosses a developing diagram, layers assemble or separate as the explanation changes. These are functional relationships, not a permanent aura or decorative floating icons. Information must GROW, TRANSFORM, CONNECT or REVEAL across the four frames, never be the identical finished graphic in every frame. Keep faces, meaningful hands and caption area clear. Different shots may let the person yield to a full-screen demonstration, POV, macro or small inset.

QUALITY: like professionally shot footage of real adults at actual everyday businesses. Unretouched natural skin texture, realistic hair, eyes, modest natural teeth, relaxed mouth, correct hands, plausible real wardrobe and accessories. All people are adults. No plastic faces, mannequin smiles, generic AI luxury interiors, game HUD, neon sci-fi hologram, flat vector people or fantasy workplace. Editorial/luxury/playful styles should remain tactile and believable; rich through intentional photography, design and material, not excessive saturation. Camera motion in the storyboard must have a reason in the explanation. Soft light accents only at the important event, surface reflections and light film texture; a social-media finish, not a heavy cinema LUT.

DIVERSITY AND EXPLANATION: Do not reduce the content to a few callout tags. Make the main explanatory construction substantial, dimensional and understandable, with components being assembled, separated, connected or transformed. It can use a model, growing diagram, environment-linked interface, pathway, layered objects, negative-space typography or a clearly motivated visual metaphor. Vary the graphic material by purpose. No default rounded rectangular label pills or frosted-glass caption boxes, no permanent side panel. Short clean type may sit directly in the physical scene with precise lines, appropriate perspective and occlusion. Different styles must not share a universal speaking portrait / tags / smiling summary layout.

Typography is an editable design reference: sophisticated, modern, elegant and legible at phone size. VERY SHORT Portuguese labels (roughly one to three words), much of the frame can be text-free. NO how-to question headline, NO generic talking-head introduction, NO recurring yellow underline, NO brush-highlight text template, NO checkmark list, NO mandatory final front-facing summary portrait. Do not print the internal instructions or four scene labels. Use the specific narrative structure and typography direction. No real brands, logos, prescription, diagnosis, savings, guaranteed results, made-up amounts, percentages or measurements. Scientific/technical/miniature or location model is an identified 'Simulação', not proof of actual microscopy, exact real geometry, a visit or data.

All important content stays fully inside its own quadrant with safe breathing space; do not crop heads, fingers, graphics or words at a grid boundary. These are STATIC FICTIONAL REFERENCE FRAMES for the intended edit, not produced animation or tracking proof.
"""
 prompt=common+'COMMERCIAL STYLE: '+s['name']+'; USE: '+s['topic']+'.\nREAL ENVIRONMENT: '+s['environment']+'.\nPERSON: '+s['presenter']+'. CLOTHES: '+s['wardrobe']+'.\nNARRATIVE: '+d['structure']+'. TYPOGRAPHY: '+d['typography']+'.\n'
 for i,(position,camera,graphic,state) in enumerate(zip(d['blocking'],d['camera'],d['graphicEvolution'],s['states'])):
  prompt+='QUADRANT '+['TOP LEFT','TOP RIGHT','BOTTOM LEFT','BOTTOM RIGHT'][i]+': CAMERA '+camera+'; PERSON POSITION '+position+'; COMMERCIAL ACTION '+state+'; EDITED INFORMATION ACTION '+graphic+'. This frame must visibly differ from the previous state in both explanation and composition.\n'
 if s['mechanism']=='instruction_reveal':prompt+='CRITICAL MEDICAL CONTENT: print only Exame / Orientação / Confirmação / Consulte o laboratório. NEVER name a test, fasting, meals, hydration, preparation duration, or a universal preparation instruction. The laboratory must confirm case-specific preparation. The visual must show paper guidance unfolding and linked to the request, not invented clinical advice.\n'
 if s['mechanism']=='risk_timeline':prompt+='CRITICAL FINANCIAL CONTENT: never say or imply longer horizon lowers risk. No rising return curve, risk score or safety ranking. Use Prazo / Liquidez / Risco as separate independent dimensions linked to a goal. Print Prazo não é garantia. Show conditional relationships and uncertainty.\n'
 if s.get('domain',{}).get('kind')=='implant_education':prompt+='CLINICAL REFERENCE: use a clean educational dental model, not a real patient operation. Anatomically plausible modest-scale teeth, implant screw within a schematic bone model, abutment and crown distinct. No blood, incision, needles, exposed wounds, surgical instructions, diagnosis, guaranteed results or fixed healing/loading schedule. A model is clearly identified Simulação; the dentist explains without performing a procedure. Real believable consultation room, mundane equipment, natural daylight and practical clothing.\n'
 if s.get('domain',{}).get('kind')=='real_estate':prompt+='PROPERTY REFERENCE: fictional illustrative property, no fake address, price, distance, registration, dimensions, claimed solar study, yield or eligibility. Models and alternate views are identified Simulação. Do not invent a recognisable real development or brand. High-end means thoughtful architecture, photography, materials and well-dressed professional presentation, not artificial gold CGI luxury. Preserve a consistent plausible property across shots.\n'
 if s['mechanism'] in ['scale_margin_layers','order_margin_decomposition']:prompt+='ACCOUNTING ACCURACY: the remainder after variable costs is Margem de contribuição, NOT profit. Approved short labels Receita / Custos variáveis / Margem de contribuição / Custos fixos / Resultado a calcular. No numeric amounts, margin percentages, Lucro label next to a contribution amount, automatic growth curve, or controlled-risk promise. An optional note Margem não é lucro is accurate. Clearly separate the later fixed-cost stage.\n'
 if s['mechanism']=='auction_factor_model':prompt+='ACCURACY: label factors Lance / Qualidade / Contexto; NO weight bars, rankings, greater/lesser importance, numeric score, platform formula or implied guaranteed sale. Use equal-sized connected criteria, then open the quality component into relevance and page experience. Label the relationship Modelo didático, not a replica of an auction engine.\n'
 if s.get('domain',{}).get('kind')=='business_education':prompt+='BUSINESS EXPLANATION: use substantial progressively built diagrams, data tables, dashboard widgets and real-object/interface connections exactly when the story calls for them, with changing viewpoints and foreground/background occlusion. Show real-looking everyday workstations, ordinary monitors, cables, notebooks, actual business tools; no futuristic command center or generic neon AI office. Any dashboard, event, chart, metric or automation is clearly identified Demonstração, not live account access or proven results. No fictional performance numbers, sales promises or causal conclusions. No invented real logos, customer personal data, credentials or a claim the integration is already installed. Short explanatory typography, not unreadable dense UI. Each transition has a purpose in the business reasoning.\n'
 jobs.append({'index':k,'id':s['id'],'sectorName':s['sectorName'],'path':'assets/presenter-realistic/'+s['id']+'.webp','prompt':prompt})
(folder/'briefs.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n');(folder/'jobs.json').write_text(json.dumps(jobs,ensure_ascii=False,indent=2)+'\n')
print(str(len(jobs))+' independently directed four-frame references; '+str(len({r['sector'] for r in rows}))+' authored sectors; 265 total presenters.')
